INSERT INTO m249_art VALUES
(0,0,$m249$الديباجة$m249$,$m249$قانون رقم 67 لسنة 2016 بإصدار قانون الضريبة على القيمة المضافة
باسم الشعب
رئيس الجمهورية
قرر مجلس النواب القانون الآتى نصه ، وقد أصدرناه :$m249$,'e05630a3058907991f849010c09c664f'),
(1,-1,$m249$المادة الأولى إصدار$m249$,$m249$يعمل بأحكام القانون المرافق فى شأن الضريبة على القيمة المضافة .$m249$,'eb4ddb531b3c0cca729759660a7f97e5'),
(2,-1,$m249$المادة الثانية إصدار$m249$,$m249$يلغى قانون الضريبة العامة على المبيعات الصادر بالقانون رقم 11 لسنة 1991 ، كما يلغى كل نص يتعارض مع أحكام هذا القانون ، على أن تستمر لجان التوفيق والتظلمات المشكلة وفقا لأحكام قانون الضريبة العامة على المبيعات المشار إليه فى نظر الطعون الضريبية المعروضة عليها لمدة ثلاثة أشهر ، على أن تحال بعدها الطعون التى لم يفصل فيها إلى اللجان المنصوص عليها فى القانون المرافق .$m249$,'33850819f67768ddb615ed3fecdba365'),
(3,-1,$m249$المادة الثالثة إصدار$m249$,$m249$يستبدل بعبارة «مصلحة الضرائب على المبيعات» أينما وردت فى القوانين والقرارات واللوائح المعمول بها عبارة «مصلحة الضرائب المصرية» .$m249$,'319c541b2afd434ea7df57ccbc968748'),
(4,-1,$m249$المادة الرابعة إصدار$m249$,$m249$يستمر المسجل فى ظل أحكام قانون الضريبة العامة على المبيعات برقم تسجيله إذا بلغت أو تجاوزت قيمة مبيعاته حد التسجيل المنصوص عليه فى القانون المرافق ، كما يستمر تسجيل المستورد لسلعة خاضعة للضريبة ، وكذلك كل منتج أو مستورد لسلعة من سلع الجدول المرافق بقانون الضريبة العامة على المبيعات إذا أدرجت ذات السلعة فى الجدول المرافق لهذا القانون مهما كان حجم معاملاته ، وعليه الالتزام بكافة أحكام القانون المرافق .
كما يلتزم بتوريد الضريبة العامة على المبيعات المستحقة عليه رفق إقراراته وفى المواعيد المقررة وفقا لأحكام هذا القانون ، وعليه الاحتفاظ بالدفاتر والسجلات والمستندات لمدة خمس سنوات تالية لتاريخ العمل بهذا القانون ، وذلك طبقا للشروط والضوابط التى تحددها اللائحة التنفيذية لهذا القانون .
وفى حالة الإخلال بأى من الأحكام المنصوص عليها فى الفقرتين السابقتين يعد المسجل متهربا وفقا لأحكام القانون المرافق .
وللمصلحة من واقع أى بيانات أو مستندات متاحة لديها تعديل الإقرارات واتخاذ الإجراءات القانونية لتحصيل ضريبة المبيعات المستحقة ، وللمسجل الحق فى الطعن فى ذلك وفقا لأحكام القانون المرافق .$m249$,'1806540ceae8b2ff8e409bac61eb562d'),
(5,-1,$m249$المادة الخامسة إصدار$m249$,$m249$يلغى تلقائيا تسجيل كل من لم يبلغ حد التسجيل المنصوص عليه فى القانون المرافق ما لم يطلب خلال ستين يوما من تاريخ العمل به استمرار تسجيله . وعلى من ألغى تسجيله تقديم إقرار ضريبى عن آخر فترة ضريبية قبل الإلغاء ، وكذا الفترات الضريبية التى لم يحل ميعاد تقديم إقراراتها خلال ثلاثين يوما من تاريخ العمل بهذا القانون مبينا به رصيد آخر المدة من الإنتاج التام والخامات والخدمات ، ويلتزم بأداء ما يستحق عليه خلال ستة أشهر من تاريخ العمل بهذا القانون ، كما يلتزم بأن يحتفظ بالدفاتر والسجلات والمستندات لمدة خمس سنوات تالية لتاريخ إلغاء تسجيله ، وعليه تمكين موظفى المصلحة من الاطلاع عليها .
وللمصلحة من واقع أى مستندات أو بيانات متاحة لديها تعديل الإقرارات واتخاذ الإجراءات القانونية لتحصيل الضريبة المستحقة ، ولمن ألغى تسجيله الطعن فى ذلك وفقا لأحكام القانون المرافق .$m249$,'a8859e8a5ce61516064e2109dbb14903'),
(6,-1,$m249$المادة السادسة إصدار$m249$,$m249$للمسجل فى ظل العمل بأحكام هذا القانون خصم قيمة الضريبة العامة على المبيعات الواجبة الخصم التى يعبر عنها الرصيد الدائن له قبل سريان أحكامه ، وكذلك ما لم يتم استنفاد خصمه أو رده من الضريبة العامة على المبيعات المسددة على الآلات والمعدات وأجزائها وقطع الغيار والضريبة السابق سدادها على المردودات من المبيعات ، كما يحق له تسوية ضريبة الجدول المستحقة على سيارات الركوب التى فى حوزته فى تاريخ العمل بهذا القانون من ضريبة المبيعات السابق سدادها عن ذات السيارات ، وذلك طبقا للشروط والضوابط التى تحددها اللائحة التنفيذية .
وترد الضريبة العامة على المبيعات السابق سدادها على السلع والخدمات المصدرة للخارج أو مدخلاتها وكذا الضريبة المسددة بالخطأ وفقا للإجراءات والقواعد الواردة فى القانون المرافق .$m249$,'b09669475663c7393fbab39c9b150770'),
(7,-1,$m249$المادة السابعة إصدار$m249$,$m249$مع عدم الإخلال بأحكام هذا القانون والقانون المرافق ، على من يستمر تسجيله وفقا لأحكام هذا القانون ، أو من يتم تسجيله وفقا للقانون المرافق توفيق أوضاعه خلال ثلاثة أشهر من تاريخ العمل به . ويعفى المسجلون من أداء الضريبة الإضافية خلال هذه الفترة عن فروق الضريبة وضريبة الجدول المستحقة قانونا إذا كان حسابها يتوقف على توفيق أوضاعهم ، وتضع اللائحة التنفيذية القرارات والقواعد الخاصة بتوفيق الأوضاع .$m249$,'1328c3105e23b6ea9c76f5ccfca4f962'),
(8,-1,$m249$المادة الثامنة إصدار$m249$,$m249$لا تخل أحكام هذا القانون والقانون المرافق بالإعفاءات المقررة بمقتضى الاتفاقيات المبرمة بين الحكومة المصرية والدول الأجنبية والمنظمات الدولية أو الإقليمية أو الاتفاقيات البترولية والتعدينية .$m249$,'ce90a652c52e24951443a60910c34021'),
(9,-1,$m249$المادة التاسعة إصدار$m249$,$m249$يصدر وزير المالية اللائحة التنفيذية لهذا القانون والقانون المرافق خلال ثلاثين يوما من تاريخ نشره . وإلى أن تصدر هذه اللائحة يستمر العمل باللوائح والقرارات المعمول بها حاليا فيما لا يتعارض مع أحكام هذين القانونين .$m249$,'7bacd4b21260dda1d7be12a0fa7fb36b'),
(10,-1,$m249$المادة العاشرة إصدار$m249$,$m249$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به من اليوم التالى لتاريخ نشره .$m249$,'ae1ca224d7e2797691b06d55d9fd8f82'),
(1,0,$m249$المادة 1$m249$,$m249$يقصد فى تطبيق أحكام هذا القانون بالألفاظ والعبارات التالية المعنى المبين قرين كل منها :
الوزير : وزير المالية .
رئيس المصلحة : رئيس مصلحة الضرائب المصرية .
المصلحة : مصلحة الضرائب المصرية .
المكلف : الشخص الطبيعى أو الشخص الاعتبارى خاصا كان أو عاما المكلف بتحصيل وتوريد الضريبة للمصلحة سواء كان منتجا أو تاجرا أو مؤديا لسلعة أو لخدمة خاضعة للضريبة بلغت مبيعاته حد التسجيل المنصوص عليه فى هذا القانون ، وكل مستورد أو مصدر أو وكيل توزيع ، لسلعة أو لخدمة خاضعة للضريبة مهما كان حجم معاملاته ، وكذلك كل منتج أو مؤد أو مستورد لسلعة أو لخدمة منصوص عليها فى الجدول المرافق لهذا القانون مهما كان حجم معاملاته .
المسجل : المكلف الذى تم تسجيله لدى المصلحة وفقا لأحكام هذا القانون .
الشخص المرتبط : كل شخص يرتبط بشخص آخر بعلاقة تؤثر فى تحديد وعاء الضريبة بما فى ذلك :
1 - الزوج والزوجة والأصول والفروع .
2 - شركة الأموال والشخص الذى يملك فيها بشكل مباشر أو غير مباشر (50%) على الأقل من عدد أو قيمة الأسهم أو من حقوق التصويت .
3 - شركة الأشخاص والشركاء والمتضامنون الموصون فيها .
4 - أى شركتين أو أكثر يملك شخص آخر (50%) على الأقل من عدد أو قيمة الأسهم أو حقوق التصويت فى كل منها .
5 - رب العمل والعمال التابعون له الذين تربطهم به علاقة عمل .
مورد الخدمة : كل شخص طبيعى أو اعتبارى يقوم بتوريد أو أداء خدمة خاضعة للضريبة .
المستورد : كل شخص طبيعى أو اعتبارى يقوم باستيراد سلع أو خدمات خاضعة للضريبة أيا كان الغرض من الاستيراد .
المقيم : الشخص الطبيعى أو الاعتبارى الذى يعد مقيما فى مصر وفقا لأحكام قانون الضريبة على الدخل .
المنشأة الدائمة : المقر الذى يتم من خلاله ممارسة النشاط ، ومنها :
محل الإدارة .
الفرع ، المكتب ، المصنع ، أو ورشة العمل .
المنجم ، أو حقل البترول أو بئر الغاز ، أو المحجر ، أو أى مكان آخر لاستخراج الموارد الطبيعية .
موقع البناء أو مشروع الإنشاء أو التركيب .
ويكون الشخص الذى له منشأة دائمة فى مصر من المخاطبين بأحكام هذا القانون .
الضريبة : الضريبة على القيمة المضافة .
الضريبة الإضافية : ضريبة بواقع (1.5%) من قيمة الضريبة أو ضريبة الجدول غير المدفوعة بما فيها الضريبة الناتجة عن تعديل الإقرار وذلك عن كل شهر أو جزء منه اعتبارا من نهاية الفترة المحددة للسداد حتى تاريخ السداد .
الضريبة على المدخلات : الضريبة التى تحملها المكلف عند شراء أو استيراد السلع بما فيها الآلات والمعدات والخدمات ، سواء كانت مباشرة أو غير مباشرة ، المتعلقة ببيع سلعة أو أداء خدمة خاضعة للضريبة .
ضريبة الجدول : ضريبة تفرض بنسب خاصة أو بقيم محددة على بيع أو استيراد السلع والخدمات المحلية أو المستوردة المنصوص عليها فى الجدول المرافق لهذا القانون وذلك بخلاف الضريبة المنصوص عليها فى الفقرة الأولى من المادة (2) من هذا القانون ما لم ينص الجدول على خلاف ذلك .
السلعة : كل شىء مادى أيا كانت طبيعته أو مصدره أو الغرض منه بما فى ذلك الطاقة الكهربائية ، سواء كان محليا أو مستوردا ، ويسترشد فى تحديد مسمى السلعة بما يرد بشأنها بملاحظات ونصوص البنود المبينة بالأقسام والفصول الواردة بجداول التعريفة الجمركية المعمول بها .
الخدمة : كل ما ليس سلعة ، سواء كان محليا أو مستوردا .
السلع والخدمات المعفاة : السلع والخدمات التى تتضمنها قائمة الإعفاءات المرافقة لهذا القانون .
البيع : انتقال ملكية السلعة أو أداء الخدمة من البائع ولو كان مستوردا إلى المشترى ، ويعد بيعا فى حكم هذا القانون ما يلى أيها أسبق :
إصدار الفاتورة .
تسليم السلعة أو تأدية الخدمة .
أداء ثمن السلعة أو مقابل الخدمة سواء كان كله أو بعضه ، أو بالأجل أو غير ذلك من أشكال أداء الثمن وفقا لشروط الدفع المختلفة .
الفاتورة الضريبية : الفاتورة التى تعد وفقا للنموذج الذى يصدر به قرار من الوزير أو من يفوضه .
الشهر : الشهر الميلادى .
الفترة الضريبية : فترة شهر تنتهى فى آخر يوم من الشهر الميلادى الذى يقدم عنه المسجل إقراره الضريبى الشهرى .
السنة المالية : اثنا عشر شهرا تبدأ مع بداية السنة المالية للمكلف وتنتهى بانتهائها .
الاستهلاك الشخصى : استعمال السلعة أو الاستفادة من الخدمة فى أغراض غير متعلقة بالنشاط .
الاستخدام الخاص : استعمال السلعة أو الاستفادة من الخدمة فى أغراض متعلقة بالنشاط ، ولا يعد انتقال السلعة من مرحلة إنتاج لأخرى داخل المنشأة وخارجها استخداما خاصا .$m249$,'8c6a3fa7dec0e83a78c5850dd5bfddcc'),
(2,0,$m249$المادة 2$m249$,$m249$تفرض الضريبة على السلع والخدمات بما فى ذلك السلع والخدمات المنصوص عليها فى الجدول المرافق لهذا القانون ، سواء كانت محلية أو مستوردة ، فى كافة مراحل تداولها ، إلا ما استثنى بنص خاص .$m249$,'98a2bea51c10cea6b544dc9cc595b99b'),
(3,0,$m249$المادة 3$m249$,$m249$يكون السعر العام للضريبة على السلع والخدمات (13%) عن العام المالى 2016/2017 ، و(14%) اعتبارا من العام المالى 2017/2018 ، [ على أن يخصص نسبة (1%) من الضريبة للإنفاق على برامج العدالة الاجتماعية ] ، واستثناء مما تقدم يكون سعر الضريبة على الآلات والمعدات المستخدمة فى إنتاج سلعة أو تأدية خدمة (5%) وذلك عدا الأتوبيسات وسيارات الركوب .
ويكون سعر الضريبة (صفر) على السلع والخدمات التى يتم تصديرها طبقا للشروط والأوضاع التى تحددها اللائحة التنفيذية .$m249$,'d67eccfc1de79c1b58afeb46e19117a7'),
(4,0,$m249$المادة 4$m249$,$m249$يلتزم المكلفون بتحصيل الضريبة والإقرار عنها وتوريدها للمصلحة فى المواعيد المنصوص عليها فى هذا القانون .$m249$,'122ae1ed8a4d48012066c51fa2a012c2'),
(5,0,$m249$المادة 5$m249$,$m249$تستحق الضريبة بتحقق واقعة بيع السلعة أو أداء الخدمة بمعرفة المكلفين فى كافة مراحل تداولها وفقا لأحكام هذا القانون وأيا كانت وسيلة بيعها أو أدائها أو تداولها بما فى ذلك الوسائل الإلكترونية .
وتستحق الضريبة بالنسبة للسلع المستوردة ، أيا كان الغرض من استيرادها بما فى ذلك ما يكون للاستهلاك الشخصى أو الاستخدام الخاص ، فى مرحلة الإفراج عنها من الجمارك بتحقق الواقعة المنشئة للضريبة الجمركية ، كما تستحق فى كافة مراحل تداولها داخل البلاد بعد الإفراج عنها ، وتطبق فى شأن السلع المستوردة القواعد المتعلقة بالأنظمة الجمركية الخاصة ، وذلك فيما لم يرد بشأنه نص خاص فى هذا القانون .
وتستحق الضريبة بالنسبة للخدمات المستوردة بتحقق واقعة تأدية الخدمة إلى متلقيها فى مصر ، أيا كانت الوسيلة التى تؤدى بها .
ولا تستحق الضريبة على السلع العابرة ، بشرط أن يتم النقل تحت رقابة مصلحة الجمارك وفقا للقواعد المقررة بقانون الجمارك .
ويعتبر فى حكم البيع قيام المكلف باستعمال السلعة أو الاستفادة من الخدمة بغرض الاستهلاك الشخصى أو الاستخدام الخاص أو التصرف فيها بأى من التصرفات القانونية .$m249$,'5f03175806bc2fbebb25fa894a59583b'),
(6,0,$m249$المادة 6$m249$,$m249$تخضع للضريبة بسعر (صفر) السلع أو الخدمات التى تصدرها مشروعات المناطق والمدن والأسواق الحرة إلى خارج البلاد .
كما تخضع للضريبة بسعر (صفر) السلع أو الخدمات الواردة لهذه المشروعات اللازمة لمزاولة النشاط المرخص به داخل المناطق والمدن والأسواق الحرة عدا سيارات الركوب .$m249$,'c0760269975d220abd35179fdfe59013'),
(7,0,$m249$المادة 7$m249$,$m249$مع عدم الإخلال بما تنص عليه الفقرة الثانية من المادة (6) من هذا القانون ، تستحق الضريبة على ما يرد من سلع أو ما يؤدى من خدمات خاضعة للضريبة وفقا لأحكام هذا القانون إلى المناطق والمدن والأسواق الحرة ، لاستهلاكها المحلى داخل هذه الأماكن .
ويعتبر الاستيراد بغرض الاتجار داخل المناطق الحرة التى تشمل مدينة بأكملها فى حكم الاستهلاك المحلى .
كما تستحق الضريبة على ما يستورد من سلع أو خدمات خاضعة للضريبة وفقا لأحكام هذا القانون من المناطق والمدن والأسواق الحرة إلى السوق المحلى داخل البلاد .
وتعامل الخدمات والسلع المصنعة فى مشروعات المناطق والمدن الحرة معاملة السلع المستوردة من الخارج عند سحبها للاستهلاك أو الاستعمال المحلى .
وتحدد اللائحة التنفيذية الحدود والقواعد المنظمة للأحكام المنصوص عليها فى هذه المادة والمادة (6) من هذا القانون .$m249$,'15e0e6ae6782e13f44c05555a74336df'),
(8,0,$m249$المادة 8$m249$,$m249$فى حالة التوقف عن ممارسة نشاط يتعلق بسلعة أو خدمة خاضعة للضريبة أو تصفيته تستحق الضريبة على السلع التى فى حوزة المسجل وقت التصرف فيها ، إلا إذا كان الخلف مسجلا أو قام بتسجيل نفسه طبقا لأحكام هذا القانون .$m249$,'929a3154bc1723b04a3b68a6794acf03'),
(9,0,$m249$المادة 9$m249$,$m249$مع عدم الإخلال بالعقوبات المنصوص عليها فى هذا القانون تخضع المبيعات المهربة والمبيعات التى تتم بالمخالفة للقواعد المقررة قانونا لفئات الضريبة النافذة فى تاريخ وقوع الجريمة أو المخالفة ، فإذا تعذر تحديده خضعت هذه المبيعات لفئات الضريبة النافذة وقت الضبط أو اكتشاف المخالفة .$m249$,'7d6269b732528e6b8a2c121589d85861'),
(10,0,$m249$المادة 10$m249$,$m249$1 - تكون القيمة الواجب الإقرار عنها والتى تتخذ أساسا لربط الضريبة بالنسبة لبيع السلع أو ما يؤدى من خدمات خاضعة للضريبة ولو كانت مستوردة ، هى القيمة المدفوعة فعلا أو الواجب دفعها بأية صورة من صور أداء الثمن وفقا للمجريات الطبيعية للأمور .
2 - تتضمن القيمة الواجب الإقرار عنها وفقا لأحكام الفقرة (1) من هذه المادة المبالغ الآتية :
( أ ) المبالغ التى يتم تحصيلها من المشترى أو متلقى الخدمة تحت أى مسمى طالما كانت بمناسبة بيع السلع أو أداء الخدمات .
(ب) جميع المصاريف العرضية كتكاليف العمولة ، والتغليف ، والتستيف ، والنقل ، والتأمين ، المفروضة من قبل البائع على المشترى أو المستورد .
3 - فى حالة بيع سلعة أو خدمة محلية أو مستوردة بين أشخاص مرتبطين يجب ألا تقل قيمة البيع عن السعر الذى يتم التعامل به بين شخصين غير مرتبطين وفقا لقوى السوق وظروف التعامل .
4 - فى حالة البيع بالمقايضة تكون قيمة السلعة المتخذة أساسا لربط الضريبة هى سعرها وفقا لقوى السوق وظروف التعامل .
5 - تتحدد القيمة الواجب الإقرار عنها بالنسبة للسلع أو الخدمات للاستخدام الخاص على أساس إجمالى التكلفة ، وتحدد هذه القيمة بالنسبة إلى السلع أو الخدمات للاستهلاك الشخصى بالسعر وفقا لقوى السوق وظروف التعامل .
6 - تتضمن القيمة بالنسبة لمبيعات التقسيط المتخذة أساسا لربط الضريبة فوائد البيع بالتقسيط فيما يزيد على سعر الائتمان والخصم المعلن من البنك المركزى فى تاريخ البيع وتحدد اللائحة التنفيذية قواعد وإجراءات البيع بالتقسيط .
7 - مع مراعاة حكم البند (8) من هذه المادة تقدر قيمة السلع المستوردة من الخارج فى مرحلة الإفراج عنها من الجمارك بالقيمة المتخذة أساسا لتحديد الضريبة الجمركية بما فيها الخدمات المرتبطة بالسلعة المستوردة مضافا إليها الضرائب الجمركية وغيرها من الضرائب والرسوم المفروضة ، على ألا تقل القيمة الواجب الإقرار عنها عند بيعها فى السوق المحلى عن القيمة المتخذة أساسا لربط الضريبة عند الإفراج الجمركى ما لم تكن هناك أسباب تجارية تبرر القيمة المخفضة ، وتحدد اللائحة التنفيذية الأسباب التى تعد تجارية .
8 - يكون وعاء الضريبة للسلع والخدمات المستوردة من المناطق والمدن الحرة كامل قيمة السلعة شاملا قيمة المكونات الأجنبية والمحلية والضريبة الجمركية المحصلة عليها وغيرها من الضرائب والرسوم المفروضة .
9 - تكون القيمة التى تتخذ أساسا لربط الضريبة على بيع المشغولات البلاتينية والذهبية والفضية والأحجار الكريمة بقيمة التشغيل (المصنعية) ويكون وعاء الضريبة عند الإفراج الجمركى على المشغولات المستوردة هو قيمة المصنعية التى تحددها مصلحة الجمارك مضافا إليها الضرائب الجمركية وغيرها من الضرائب والرسوم المفروضة ، وتحدد اللائحة التنفيذية ما يعتبر من الأحجار الكريمة وقواعد حساب قيمة التشغيل (المصنعية) .
10 - تكون القيمة التى تتخذ أساسا لربط الضريبة بالنسبة لمبيعات السلع والخدمات الواردة بالجدول المرافق لهذا القانون على النحو الآتى :
أولا - بالنسبة لمبيعات السلع والخدمات المحلية :
القيمة المدفوعة فعلا أو الواجب دفعها بأية صورة من صور أداء الثمن وفقا للمجريات الطبيعية للأمور مضافا إليها ضريبة الجدول .
ثانيا - بالنسبة للسلع والخدمات المستوردة :
( أ ) السلع المستوردة : القيمة المتخذة أساسا لتحديد الضريبة الجمركية مضافا إليها الضرائب الجمركية وغيرها من الضرائب والرسوم المفروضة ، وضريبة الجدول .
(ب) الخدمات المستوردة : القيمة المدفوعة فعلا أو الواجب دفعها بأية صورة من صور أداء الثمن وفقا للمجريات الطبيعية للأمور مضافا إليها ضريبة الجدول .
11 - تكون القيمة التى تتخذ أساسا لربط الضريبة على السلع الجديدة التى يشتريها المكلف ثم يقوم ببيعها بعد استعمالها محليا لمدة لا تقل عن سنتين بواقع (30%) من القيمة البيعية ، مع عدم إعمال أحكام الخصم المنصوص عليها فى المادة (22) من هذا القانون عند البيع .
12 - للوزير بالاتفاق مع الوزير المختص أن يصدر قوائم بقيم بعض السلع أو الخدمات أو وضع أسس محاسبية تتخذ أساسا لربط الضريبة .$m249$,'cfe21fc04498cc31fcec72231be63ce7'),
(11,0,$m249$المادة 11$m249$,$m249$تضاف قيمة الضريبة إلى سعر السلع أو الخدمات بما فى ذلك السلع والخدمات المسعرة جبريا والمحددة الربح .
وتعدل أسعار العقود المبرمة بين مكلفين أو بين أطراف أحدها مكلف والسارية وقت فرض الضريبة وضريبة الجدول أو عند تعديل فئاتها بذات قيمة عبء الضريبة أو تعديلها ، وتحدد اللائحة التنفيذية قواعد تطبيق الفقرة الثانية من هذه المادة .$m249$,'87e08a18addaa14de3a3039e705ffb6b'),
(12,0,$m249$المادة 12$m249$,$m249$يلتزم المسجل بأن يحرر فاتورة ضريبية عند بيع السلعة أو أداء الخدمة الخاضعة للضريبة ، على أن تتضمن اسم المشترى ورقم تسجيله إن كان مسجلا ، وتحدد اللائحة التنفيذية البيانات التى تتضمنها الفواتير والإجراءات التى تكفل انتظامها وتيسير مراقبتها ، ومراجعتها .
وللوزير وضع نظم مبسطة لأغراض ربط الضريبة وضريبة الجدول للمنشآت التى يتعذر عليها إصدار فواتير ضريبية عند كل عملية بيع .
كما يجوز للوزير أو من يفوضه فى بعض الحالات إلزام المسجل عدم إصدار أية فواتير عن سلعة أو خدمة خاضعة للضريبة وضريبة الجدول ما لم تكن الفواتير معتمدة من المصلحة .$m249$,'a810ba5ec46549c275cba86b851fdec0'),
(13,0,$m249$المادة 13$m249$,$m249$يلتزم المسجل بإمساك سجلات ودفاتر محاسبية منتظمة يدويا أو إلكترونيا يسجل فيها أولا بأول العمليات التى يقوم بها ، ويجب أن يحتفظ بهذه السجلات والدفاتر والمستندات بما فيها صور الفواتير لمدة خمس سنوات تالية لانتهاء السنة المالية التى أجرى فيها القيد بهذه السجلات والدفاتر .
وتحدد اللائحة التنفيذية الحدود والقواعد والإجراءات والسجلات والدفاتر التى يلتزم المسجل بإمساكها يدويا أو إلكترونيا ، والبيانات التى يتعين إثباتها فيها والمستندات التى يجب الاحتفاظ بها .$m249$,'27a92bb8ebce32dd3ec20d10703032d5'),
(14,0,$m249$المادة 14$m249$,$m249$على كل مسجل أن يقدم للمصلحة إقرارا شهريا عن الضريبة وضريبة الجدول المستحقة أو إحداهما بحسب الأحوال وذلك على النموذج المعد لهذا الغرض خلال الشهرين التاليين لانتهاء الفترة الضريبية على أن يقدم إقرار شهر إبريل وتؤدى الضريبة وضريبة الجدول عنه فى موعد غايته اليوم الخامس عشر من شهر يونيو .
كما يلتزم المسجل بتقديم هذا الإقرار ولو لم يكن قد حقق بيوعا أو أدى خدمات خاضعة للضريبة خلال الفترة الضريبية .
وإذا لم يقدم المسجل الإقرار فى الميعاد المنصوص عليه فى هذه المادة يكون للمصلحة الحق فى تقدير الضريبة عن الفترة الضريبية مع بيان الأسس التى استندت إليها فى التقدير ، وذلك كله دون الإخلال بالمساءلة الجنائية .$m249$,'3cebe1b27a9c869819d506af03e90f4c'),
(15,0,$m249$المادة 15$m249$,$m249$على المصلحة تعديل الإقرار الذى يقدمه المسجل إذا تبين لها أن قيمة الضريبة الواجب الإقرار عنها تختلف عما ورد بهذا الإقرار عن أية فترة ضريبية ، وذلك خلال خمس سنوات تبدأ من تاريخ انتهاء المدة المحددة لتقديم الإقرار عن الفترة الضريبية وفقا لحكم المادة (14) من هذا القانون .
وإذا قامت المصلحة بتعديل الإقرار بعد مضى السنوات الثلاث الأولى من تاريخ انتهاء المدة المحددة لتقديمه لا يجوز لها حساب الضريبة الإضافية عن الفترة التالية لانتهاء مدة السنوات الثلاث المشار إليها وحتى تاريخ إخطار المسجل بهذا التعديل .
وتخطر المصلحة المسجل بالتعديل والأسس التى استندت عليها على النموذج المعد لهذا الغرض بخطاب موصى عليه مصحوبا بعلم الوصول أو بأية وسيلة الكترونية لها حجية فى الإثبات وفقا لقانون التوقيع الإلكترونى أو بأية وسيلة كتابية يتحقق بها العلم اليقينى .
ولصاحب الشأن فى جميع الأحوال ، الطعن فى تقدير المصلحة وفقا للإجراءات المنصوص عليها فى هذا القانون .$m249$,'d461c164316e4bd760eb91e4f32c1557'),
(16,0,$m249$المادة 16$m249$,$m249$على كل شخص طبيعى أو اعتبارى يبيع سلعة أو يؤدى خدمة خاضعة للضريبة بلغ أو جاوز إجمالى قيمة مبيعاته على السلع والخدمات الخاضعة للضريبة والمعفاة منها خلال الاثنى عشر شهرا السابقة على تاريخ العمل بهذا القانون مبلغ خمسمائة ألف جنيه، أن يتقدم إلى المصلحة بطلب لتسجيل اسمه وبياناته على النموذج المعد لهذا الغرض وذلك خلال ثلاثين يوما من تاريخ بلوغ رقم مبيعاته حد التسجيل ، وأما من تبلغ قيمة مبيعاته هذا المبلغ بعد تاريخ العمل بهذا القانون فى أية سنة مالية أو جزء منها فعليه أن يتقدم للمصلحة لتسجيل اسمه على النحو المشار إليه، ولا يسرى الالتزام بالتسجيل على الشخص الطبيعى الذى لا يباشر نشاط بيع سلعة أو أداء خدمة إذا بلغت مبيعاته الحد المشار إليه .
وعلى كل مستورد لسلعة أو خدمة خاضعة للضريبة بقصد الاتجار أو مصدر أو وكيل توزيع أن يسجل نفسه لدى المصلحة مهما كان حجم معاملاته .
ويتعين على المصلحة إخطار المكلف بالتسجيل خلال الأربعة عشر يوما التالية لتاريخ طلب التسجيل، وتسرى عليه أحكام هذا القانون من تاريخ التسجيل .
وفى حالة عدم تقدم المكلف للمصلحة للتسجيل يعد مسجلا بحكم القانون، وتسرى عليه أحكامه من تاريخ بلوغ قيمة مبيعاته من السلع أو الخدمات حد التسجيل ، مع عدم الإخلال بأحكام المادة (68) من هذا القانون .
ويجوز بقرار من الوزير تعديل حد التسجيل المشار إليه .$m249$,'5a1fe314a7b40d336bff8a85e9812e0a'),
(17,0,$m249$المادة 17$m249$,$m249$يجب على كل شخص غير مقيم وغير مسجل بالمصلحة، يقوم ببيع سلع أو أداء خدمات خاضعة للضريبة لشخص غير مسجل داخل البلاد ولا يمارس نشاطا من خلال منشأة دائمة فى مصر، أن يعين ممثلا له أو وكيلا عنه فى مصر يكون مسئولا عن القيام بجميع التزامات المكلف المنصوص عليها فى هذا القانون، بما فى ذلك التسجيل وسداد الضريبة والضريبة الإضافية وغيرها من الضرائب المستحقة وفقا لأحكام هذا القانون .
ويجب على الشخص المقيم أن يتأكد من أن الشخص غير المقيم قد قام بتعيين ممثل له أو كيل عنه فى مصر، وفى حالة عدم قيام الشخص غير المقيم بذلك يلتزم المقيم المتعامل معه بسداد الضريبة وغيرها من الضرائب المستحقة وفقا لأحكام هذا القانون إلى المصلحة دون إخلال بحقه فى الرجوع على الشخص غير المقيم .$m249$,'0271fdc123dc93968a6cd9aeac0f8fa1'),
(18,0,$m249$المادة 18$m249$,$m249$يجوز للشخص الطبيعى أو الاعتبارى الذى لم يبلغ حد التسجيل أن يتقدم إلى المصلحة لتسجيل اسمه وبياناته طبقا للشروط والأوضاع والإجراءات التى تحددها اللائحة التنفيذية ، ويعتبر فى حالة التسجيل من المكلفين المخاطبين بأحكام هذا القانون .$m249$,'8bcd294d7ac0313a5a83b3ff7e97a68f'),
(19,0,$m249$المادة 19$m249$,$m249$تمسك المصلحة سجلا تقيد به بيانات طلبات التسجيل بعد مراجعتها والتحقق من صحتها وتسلم لكل مسجل شهادة بذلك .
وتحدد اللائحة التنفيذية الاشتراطات والقواعد والإجراءات الخاصة بشهادات التسجيل والبيانات التى تتضمنها .$m249$,'037d95a08c35e68360be9b8a999b53ac'),
(20,0,$m249$المادة 20$m249$,$m249$يلتزم كل مسجل بإخطار المصلحة كتابة بأى تغييرات تحدث على البيانات السابق تقديمها بطلب التسجيل وذلك خلال واحد وعشرين يوما من حدوث تلك التغييرات .$m249$,'2861d08a717decc2aeb57fbc4bc5c5f4'),
(21,0,$m249$المادة 21$m249$,$m249$يجوز لرئيس المصلحة أن يلغى التسجيل فى الحالات وبالشروط والأوضاع التى تحددها اللائحة التنفيذية .$m249$,'a3dc072f7df84752102472f4a97252cc'),
(22,0,$m249$المادة 22$m249$,$m249$للمسجل عند حساب الضريبة أن يخصم من الضريبة المستحقة على قيمة مبيعاته من السلع والخدمات ما سبق سداده أو حسابه من ضريبة على المردودات من مبيعاته وما سبق تحميله من هذه الضريبة على مدخلاته بما فيها الضريبة السابق تحميلها على السلع والخدمات المبيعة بمعرفة المسجل فى كل مرحلة من مراحل توزيعها طبقا للحدود وبالشروط والأوضاع التى تحددها اللائحة التنفيذية .
ويسرى حكم الفقرة الأولى من هذه المادة على :
1 - مبيعات السلع والخدمات الموردة إلى الجهات المشار إليها فى المادة الثامنة من مواد الإصدار والمادة (23) من هذا القانون .
2 - مبيعات السلع والخدمات الممولة بمنح صدر قانون بإعفائها من الضريبة.
ويكون الخصم فى حدود المستحق من الضريبة، ويرحل ما لم يتم خصمه إلى الفترات الضريبية التالية حتى يتم الخصم بالكامل .
ولا يسرى الخصم المنصوص عليه فى الفقرة الأولى من هذه المادة على ما يأتى :
1 - ضريبة الجدول، سواء على سلع أو خدمات خاضعة بذاتها أم كمدخلات فى سلع أو خدمات خاضعة للضريبة، وذلك فيما لم يرد به نص خاص فى هذا القانون .
2 - ضريبة المدخلات المدرجة ضمن التكلفة .
3 - السلع والخدمات المعفاة .$m249$,'69fa153810c1d4a1d3c1b636d0196808'),
(23,0,$m249$المادة 23$m249$,$m249$يعفى من الضريبة وبشرط المعاملة بالمثل وفى حدود هذه المعاملة ووفقا لبيانات وزارة الخارجية :
1 - ما يشترى أو يستورد للاستعمال الشخصى لأعضاء السلكين الدبلوماسى والقنصلى الأجانب العاملين غير الفخريين المعينين فى الجداول التى تصدرها وزارة الخارجية ، وكذلك ما يشترى أو يستورد للاستعمال الشخصى لأزواجهم وأولادهم القصر.
2 - ما يشترى أو يستورد للسفارات والمفوضيات والقنصليات غير الفخرية للاستعمال الرسمى عدا المواد الغذائية والمشروبات الروحية والأدخنة .
ويحدد عدد السيارات التى يتناولها الإعفاء طبقا للبندين 1 ، 2 بسيارة واحدة للاستعمال الشخصى وخمس سيارات للاستعمال الرسمى للسفارة أو المفوضية وسيارتين للاستعمال الرسمى للقنصلية، ويجوز للوزير بالاتفاق مع وزير الخارجية زيادة هذا العدد .
3 - ما يستورد للاستعمال الشخصى بشرط المعاينة من أمتعة شخصية وأثاث وأدوات منزلية، وكذلك سيارة واحدة مستعملة لكل موظف أجنبى من العاملين فى البعثات الدبلوماسية أو القنصلية الذين لا يستفيدون من الإعفاء المقرر فى البند (1) من هذه الفقرة بشرط أن يتم الورود خلال ستة أشهر من وصول المستفيد من الإعفاء، ويجوز للوزير بالاتفاق مع وزير الخارجية مد هذا الأجل .
وتمنح الإعفاءات المشار إليها فى هذه المادة بعد اعتماد طلبات الإعفاء من رئيس البعثة الدبلوماسية أو القنصلية حسب الأحوال والتصديق على ذلك من وزارة الخارجية .$m249$,'2c26667ab14d671f7590badfa3a44ad1'),
(24,0,$m249$المادة 24$m249$,$m249$يحظر التصرف فى الأشياء التى أعفيت طبقا لأحكام المادة (23) من هذا القانون فى غير الأغراض التى أعفيت من أجلها خلال السنوات الخمس التالية للإعفاء قبل إخطار المصلحة وسداد الضريبة المستحقة وفقا لحالة هذه الأشياء وقيمتها وفئة الضريبة السارية فى تاريخ السداد ما لم يقض نظام المعاملة بالمثل بغير ذلك .
وتحدد اللائحة التنفيذية القواعد والإجراءات المنظمة لذلك .$m249$,'ebf96aac103175cb2292fdc477d7457e'),
(25,0,$m249$المادة 25$m249$,$m249$يجوز بقرار من الوزير بالاتفاق مع وزير الخارجية إعفاء ما يستورد للاستعمال الشخصى لبعض ذوى المكانة من الأجانب بقصد المجاملة الدولية .$m249$,'eef56d58204290e4d75c3a084e66e1bd'),
(26,0,$m249$المادة 26$m249$,$m249$يعفى من الضريبة فى الحدود وبالشروط والأوضاع التى تحددها اللائحة التنفيذية ما يأتى :
1 - العينات التى تستهلك فى أغراض التحليل بالمعامل الحكومية .
2 - الأشياء والمتعلقات الشخصية المجردة من أية صفة تجارية كالنياشين والميداليات والجوائز الرياضية والعلمية .
3 - المهمات التى ترد من الخارج دون قيمة بدل تالف أو ناقص عن رسائل سبق توريدها أو رفض قبولها وحصلت الضريبة عليها كاملة فى حينها، بشرط أن تتحقق مصلحة الجمارك من ذلك .
4 - الأمتعة الشخصية الخاصة بالقادمين من الخارج .
5 - الأشياء التى تم سداد الضريبة عليها وصدرت للخارج ثم أعيد استيرادها بذاتها بشرط أن تتحقق مصلحة الجمارك من ذلك .$m249$,'17c4836179d40a3f419582d5db51f299'),
(27,0,$m249$المادة 27$m249$,$m249$يجوز بقرار من الوزير بالاتفاق مع الوزير المختص إعفاء بعض السلع من الضريبة فى الحالتين الآتيتين :
1 - الهبات والتبرعات والهدايا للجهاز الإدارى للدولة أو وحدات الإدارة المحلية .
2 - ما يستورد للأغراض العلمية أو التعليمية أو الثقافية بواسطة المعاهد العلمية والتعليمية ومعاهد البحث العلمى .$m249$,'c021c125f7db3038d088dc841209d10a'),
(28,0,$m249$المادة 28$m249$,$m249$تعفى من الضريبة كافة السلع والمعدات والأجهزة والخدمات المعنية فى هذا القانون اللازمة لأغراض التسليح للدفاع والأمن القومى وكذلك الخامات ومستلزمات الإنتاج والأجزاء الداخلة فى تصنيعها .$m249$,'a2b926915975bc7dc0cb592e5ee6ab3c'),
(29,0,$m249$المادة 29$m249$,$m249$مع مراعاة حكم المادة الثامنة من قانون الإصدار لا تسرى الإعفاءات الضريبية المنصوص عليها فى القوانين والقرارات الأخرى على هذه الضريبة مالم ينص على الإعفاء منها صراحة .$m249$,'52ae93a559d381306220e2e81f2e56de'),
(30,0,$m249$المادة 30$m249$,$m249$ترد الضريبة طبقا للشروط والإجراءات وفى الحدود التى تبينها اللائحة التنفيذية ، خلال خمسة وأربعين يوما من تاريخ تقديم الطلب مؤيدا بالمستندات فى الحالات الآتية :
1 - الضريبة السابق سدادها أو تحميلها على السلع والخدمات التى يتم تصديرها، سواء صدرت بحالتها أو أدخلت فى سلع أو خدمات أخرى، بما لا يجاوز الرصيد الدائن، بشرط توريد قيمة الصادرات إلى أحد البنوك الخاضعة لإشراف البنك المركزى وفقا للضوابط التى يحددها ، أو وفقا لأى من طرق السداد أو التسويات الأخرى التى تحددها اللائحة التنفيذية وذلك كله بشرط ألا تقل قيمة الصادرات عن قيمة مدخلاتها .
2 - الضريبة التى حصلت بطريق الخطأ .
3 - الرصيد الدائن الذى مر عليه أكثر من ست فترات ضريبية متتالية .
4 - الضريبة السابق سدادها على الآلات والمعدات التى تستخدم فى إنتاج سلعة أو أداء خدمة خاضعة للضريبة، وذلك عند تقديم أول إقرار ضريبى عدا الأتوبيسات وسيارات الركوب إلا إذا كان استخدامها هو النشاط المرخص به للمنشأة .
وفى جميع الأحوال يجب أن يكون من بين المستندات الدالة على أحقية المكلف فى خصم الضريبة أو ردها شهادة موقعة من محاسب مقيد بجدول المحاسبين والمراجعين تفيد ذلك .$m249$,'2f79527274c3d94ddfda97c92ec24fe9'),
(31,0,$m249$المادة 31$m249$,$m249$على المسجل أداء حصيلة الضريبة دوريا للمصلحة رفق إقراره الشهرى وفى الموعد المنصوص عليه فى المادة (14) من هذا القانون ، وذلك طبقا للقواعد والإجراءات التى تحددها اللائحة التنفيذية .
وتؤدى الضريبة على السلع المستوردة فى مرحلة الإفراج عنها من الجمارك وفقا للإجراءات المقررة لسداد الضريبة الجمركية ، ولا يجوز الإفراج النهائى عن هذه السلع قبل سداد الضريبة المستحقة بالكامل .
وفى حالة عدم أداء الضريبة فى الموعد المحدد تستحق الضريبة الإضافية ويتم تحصيلها مع الضريبة وبذات إجراءاتها .$m249$,'043a96c50da4f007c5efa1489801bcaf'),
(32,0,$m249$المادة 32$m249$,$m249$إذا قام شخص غير مقيم وغير مسجل بالمصلحة ببيع خدمة داخل البلاد لمسجل غير لازمة لمزاولة نشاطه أو لجهة حكومية أو هيئة عامة أو اقتصادية أو أية جهة أخرى، يلتزم المستفيد من الخدمة بحساب الضريبة المستحقة عليها وسدادها للمصلحة خلال ثلاثين يوما من تاريخ البيع فى حالة عدم قيام الشخص غير المقيم وغير المسجل بتعيين ممثل له أو وكيل عنه .
وفى حالة قيام المسجل باستيراد خدمة لازمة لممارسة نشاطه الخاضع للضريبة فإنه يعامل كمستورد ومورد لتلك الخدمة فى ذات الوقت .
وفى حالة عدم أداء الضريبة فى الموعد المحدد تستحق الضريبة الإضافية ويتم تحصيلها مع الضريبة وبذات إجراءاتها .$m249$,'e5748d594b4120ec97f4a3d8c148915b'),
(33,0,$m249$المادة 33$m249$,$m249$يعتبر إصدار الفاتورة من مؤدى الخدمة هو الواقعة المنشئة للضريبة وفقا لأحكام هذا القانون بالنسبة للخدمات ذات الطبيعة المستمرة، وتحدد اللائحة التنفيذية ماهية هذه الخدمات .$m249$,'7777f0aa16d01ef217cfd316b3dbc4d8'),
(34,0,$m249$المادة 34$m249$,$m249$يتبع فى تحصيل الضريبة والمبالغ الأخرى المستحقة بمقتضى هذا القانون أحكام القانون رقم 308 لسنة 1955 فى شأن الحجز الإدارى والأحكام والإجراءات المنصوص عليها فى هذا القانون .
وتسرى أحكام الفقرة الأولى من هذه المادة على الشركات والمنشآت ، أيا كان النظام القانونى المنشأة وفقا له .$m249$,'da82afb88ce1a45be159568340b65af6'),
(35,0,$m249$المادة 35$m249$,$m249$تقع المقاصة بقوة القانون بين ما هو مستحق للمسجل لدى المصلحة وما يكون مستحقا عليه وواجب الأداء بموجب أى قانون ضريبى تطبقه المصلحة أو أى من المصالح الإيرادية التابعة لوزارة المالية .$m249$,'566ea05eb31c17fa19023b71676dfab2'),
(36,0,$m249$المادة 36$m249$,$m249$تفرض ضريبة الجدول على بيع أو أداء أو استيراد السلع والخدمات المنصوص عليها فى الجدول المرافق، ويكون سعر ضريبة الجدول وفقا للنسب أو القيم المحددة قرين السلع والخدمات المنصوص عليها فيه، وذلك بالإضافة للضريبة المنصوص عليها فى المادة (2) من هذا القانون .
ويكون سعر ضريبة الجدول (صفر) على السلع والخدمات التى يتم تصديرها، وذلك طبقا للشروط والأوضاع التى تحددها اللائحة التنفيذية.
ولا تفرض ضريبة الجدول مرة أخرى إلا إذا حدث تغيير فى حالة السلعة ، ولا يعد تغييرا فى حالة السلعة عملية التعبئة أو إعادة التعبئة أو التكرير أو التنقية أو الطحن ، مع عدم الإخلال باستحقاق الضريبة على السلع والخدمات الواردة بالجدول المرافق ، وذلك كله مالم ينص فى الجدول على خلاف ذلك .$m249$,'8cdf6f2595f6ede19a099a6ff08a5491'),
(37,0,$m249$المادة 37$m249$,$m249$للمسجل الحق فى تسوية الضريبة السابق سدادها على أجزاء الآلات والمعدات وقطع الغيار المستخدمة فى إنتاج سلع وخدمات خاضعة لضريبة الجدول فقط من قيمة ضريبة الجدول فى حدود المستحق منها حتى يتم استنفادها .
وللمسجل الحق فى تسوية ضريبة الجدول السابق سدادها على مردودات مبيعاته من ضريبة الجدول المستحقة وفقا للشروط والأوضاع التى تحددها اللائحة التنفيذية .$m249$,'b7c64d981ff0f759a689dc58c7e16e72'),
(38,0,$m249$المادة 38$m249$,$m249$تستحق ضريبة الجدول على السلع والخدمات المنصوص عليها فى الجدول المرافق لمرة واحدة عند تحقق واقعة بيعها أو أدائها لأول مرة أو استيرادها، وذلك دون الإخلال باستحقاق الضريبة المنصوص عليها فى الباب الثانى من هذا القانون .
ويسرى حكم الفقرة الأولى من هذه المادة على السلع والخدمات المنصوص عليها فى الجدول المرافق عند التصرف فيها فى صورة سلع وخدمات مجانية أو عروض ترويجية ، وتتحدد القيمة فى هذه الحالة وفقا لقوى السوق وظروف التعامل وتبين اللائحة التنفيذية ماهية العروض الترويجية .$m249$,'c134b0949f9e049aa9ff2a7e2cc728bc'),
(39,0,$m249$المادة 39$m249$,$m249$تكون القيمة الواجب الإقرار عنها والتى تتخذ أساسا لربط ضريبة الجدول بالنسبة للسلع أو الخدمات المنصوص عليها فى الجدول المرافق على النحو الآتى :
( أ ) بالنسبة للسلع والخدمات المحلية :
القيمة المدفوعة فعلا أو الواجب دفعها بأية صورة من صور أداء الثمن وفقا للمجريات الطبيعية للأمور .
(ب) بالنسبة للسلع والخدمات المستوردة :
القيمة التى تتخذ أساسا لربط الضريبة الجمركية مضافا إليها الضريبة الجمركية وغيرها من الضرائب والرسوم المفروضة .
وذلك كله ما لم ينص فى الجدول المرافق على خلاف ذلك .$m249$,'32a5a8bfed43f664c4741d07afe3fe6e'),
(40,0,$m249$المادة 40$m249$,$m249$فى حالة إخضاع سلعة أو خدمة لضريبة الجدول أو زيادة الفئة المفروضة عليها، يلتزم المستوردون وتجار الجملة ونصف الجملة والتجزئة والموزعون بتقديم بيان إلى المصلحة بالرصيد الموجود لديهم من هذه السلع أو الخدمات فى اليوم السابق لسريان ضريبة الجدول الجديدة أو المزيدة، ويكون تقديم هذا البيان خلال خمسة عشر يوما من هذا التاريخ، وتستحق ضريبة الجدول الجديدة أو المزيدة فى تاريخ تقديم هذا البيان، ويجب أداء ضريبة الجدول المستحقة على هذه السلع والخدمات خلال المدة التى يحددها رئيس المصلحة على ألا تجاوز ستة أشهر من تاريخ استحقاقها .$m249$,'c24b5eda9b7926001c5ae41224e7132f'),
(41,0,$m249$المادة 41$m249$,$m249$على كل منتج أو مؤدى أو مستورد لسلعة أو لخدمة من السلع أو الخدمات المنصوص عليها بالجدول المرافق لهذا القانون أن يسجل نفسه لدى المصلحة مهما كان حجم مبيعاته أو إنتاجه طبقا للقواعد والإجراءات التى تحددها اللائحة التنفيذية .$m249$,'05daae3367be221752f052314e602131'),
(42,0,$m249$المادة 42$m249$,$m249$لا يجوز إنشاء أو تشغيل أى مصنع أو معمل لإنتاج أية سلعة أو تأدية أية خدمة من السلع والخدمات المنصوص عليها فى الجدول المرافق لهذا القانون، إلا بعد الحصول على ترخيص بذلك من الجهة الإدارية المختصة طبقا للشروط والأوضاع التى يقررها الوزير المختص بالاتفاق مع الوزير .
وعلى كل منتج لسلعة أو مؤدى خدمة من هذه السلع أو الخدمات إخطار المصلحة بتوقف العمل بالمصنع أو المعمل أو المقر الذى يتم من خلاله ممارسة النشاط لأى سبب كان، سواء توقف كلى أو جزئى ، وعليه كذلك إخطار المصلحة فور انتهاء فترة التوقف، وذلك كله على النحو الذى يصدر به قرار من رئيس المصلحة .$m249$,'a4cabe7e00ddef5ed495d136bd752741'),
(43,0,$m249$المادة 43$m249$,$m249$تسرى أحكام هذا القانون على السلع والخدمات المنصوص عليها فى الجدول المرافق، وذلك فيما لم يرد به نص خاص فى هذا الباب والجدول المرافق .$m249$,'ca233efca67a4ce115bf6fd9eaa4c536'),
(44,0,$m249$المادة 44$m249$,$m249$مع عدم الإخلال بما ورد فى شأنه نص خاص فى هذا القانون، يحظر التصرف فى أى من السلع المعفاة من الضريبة وضريبة الجدول أو استعمالها فى غير الغرض الذى أعفيت من أجله خلال السنوات الخمس التالية للإعفاء إلا بعد إخطار المصلحة وسداد الضرائب المستحقة وفقا لقيمتها وفئة الضريبة السارية فى تاريخ التصرف .
ويسرى الحظر المنصوص عليه فى الفقرة الأولى من هذه المادة على الآلات والمعدات السابق رد الضريبة عليها وفقا لأحكام البند (4) من المادة (30) من هذا القانون .
وفى جميع الأحوال، يجب ألا تجاوز قيمة الضريبة المستحقة قيمة الضريبة السابق الإعفاء منها أو ردها .$m249$,'b03a190843b8bf114f12ac11230d77ab'),
(45,0,$m249$المادة 45$m249$,$m249$للمصلحة عند الاقتضاء أخذ عينات من بعض السلع للتحليل وأن تستعين بمن تراه من الخبراء .
ولصاحب الشأن أن يطلب إعادة التحليل على حسابه، ويصدر قرار من الوزير يحدد فيه طرق وإجراءات أخذ العينات .$m249$,'f498fda3658cbba5203407faf97fd23f'),
(46,0,$m249$المادة 46$m249$,$m249$تحدد اللائحة التنفيذية المبالغ التى تحصلها المصلحة ثمنا للمطبوعات وطوابع البندرول والعلامات المميزة أو مقابل وضع أختام أو مصاريف التحليل أو مقابل الخدمات التى يقوم بها موظفو المصلحة وكذلك أجور العمل الذى يقومون به لحساب ذوى الشأن فى غير أوقات العمل الرسمية .
ولا تدخل هذه المبالغ فى نطاق الإعفاء أو رد الضريبة أو ضريبة الجدول المشار إليهما فى هذا القانون .$m249$,'68a8a535b262f21b8fe56145db99da00'),
(47,0,$m249$المادة 47$m249$,$m249$دون الإخلال بأحكام قانون الجمارك ،للمصلحة حق التصرف فى المضبوطات وأدوات التهريب ووسائل النقل التى يحكم بمصادرتها، وذلك وفقا للقواعد التى تحددها اللائحة التنفيذية .
ويجوز للمصلحة بأمر قضائى أن تتصرف قبل صدور الحكم فى المضبوطات القابلة للتلف أو النقصان أو الفقد كما يكون لها الحق فى إعدام السلع المحظور تداولها أو الضارة بالصحة العامة أو التى يخشى من طرحها للبيع على أمن وسلامة المواطنين وذلك بعد استطلاع رأى الجهات الفنية المختصة .$m249$,'05e9d525dbac4d3799479d69b98d3521'),
(48,0,$m249$المادة 48$m249$,$m249$فى جميع الأحوال لا يجوز للمصلحة إجراء تقدير الضريبة أو ضريبة الجدول أو تعديل الإقرار المقدم من المسجل إلا بناء على بيانات أو مستندات متاحة لديها وخلال خمس سنوات تبدأ من تاريخ انتهاء المدة المحددة قانونا لتقديم الإقرار عن الفترة الضريبية وتكون هذه المدة ست سنوات إذا كان المسجل متهربا من أداء الضريبة .
وتنقطع المدة بأى سبب من أسباب قطع التقادم المنصوص عليها فى القانون المدنى أو بالإخطار بربط الضريبة أو التنبيه على المسجل بأدائها أو بالإحالة إلى لجان الطعن .$m249$,'7e92afedeed6513e7f4cdeba0e72bf3c'),
(49,0,$m249$المادة 49$m249$,$m249$تسرى بالنسبة للسلع المستوردة الخاضعة للضريبة والتى لم يتم الإفراج عنها من الجمارك أحكام المخالفات والتهرب المنصوص عليها فى قانون الجمارك .$m249$,'24ced0653845ff644a0e387c81ed82bf'),
(50,0,$m249$المادة 50$m249$,$m249$يجوز إسقاط الديون المستحقة للمصلحة على المسجل وذلك فى الأحوال الآتية :
1 - إذا قضى نهائيا بإفلاسه وأقفلت التفليسة .
2 - إذا غادر البلاد لمدة عشر سنوات بغير أن يترك أموالا.
3 - إذا ثبت عدم وجود مال يمكن التنفيذ عليه لدى المدين .
4 - إذا توفى عن غير تركة .
وتختص بالإسقاط لجان يصدر بتشكيلها قرار من الوزير أو من يفوضه وتعتمد توصياتها بقرار من رئيس المصلحة ويجوز سحب قرار الإسقاط إذا تبين أنه قام على سبب غير صحيح .
وتحدد اللائحة التنفيذية قواعد تشكيل هذه اللجان .$m249$,'2d600ba879b843c0c8cd9360b2921d57'),
(51,0,$m249$المادة 51$m249$,$m249$يكون للضريبة وضريبة الجدول والضريبة الإضافية وغيرها من المبالغ الأخرى المستحقة للمصلحة بمقتضى هذا القانون امتياز على جميع أموال المدينين بها أو المكلفين بتحصيلها وتوريدها إلى المصلحة بحكم القانون وذلك بالأولوية على كافة الديون الأخرى عدا المصاريف القضائية .$m249$,'4e3470fa4e4c6535aedc2f3f6fc0132f'),
(52,0,$m249$المادة 52$m249$,$m249$تحدد اللائحة التنفيذية نظم الرقابة اللازمة على دفاتر ومستندات المسجلين ، ونظم الحسابات الآلية وأجهزة البيع الالكترونى التى يستخدمها المسجلون فى مباشرة نشاط بيع سلعة أو أداء أو استيراد خدمة خاضعة للضريبة أو ضريبة الجدول ، بهدف التحقق من التزام المسجل بحسابهما وفقا لأحكام هذا القانون .
وللوزير أو من يفوضه تقرير الأحكام والقواعد الإجرائية اللازمة لتطبيق أحكام هذا القانون بما يتماشى وطبيعة نشاط بعض المسجلين .$m249$,'090ddd78d0a4099c9609aa690fb3af8a'),
(53,0,$m249$المادة 53$m249$,$m249$للوزير وضع نظام أو أكثر يمكن المصلحة من الحصول الكترونيا على الإقرارات الضريبية وصور أو بيانات الفواتير الضريبية المصدرة من المسجل أو إليه ، وعلى المسجل الالتزام بإخطار المصلحة بصور الفواتير أو بياناتها وقسائم تحصيل ماكينات تسجيل النقدية وفقا لهذا النظام عند طلبها .
كما يجوز للوزير أو من يفوضه إلزام المنشآت أو بعضها استخدام ماكينات تسجيل المتحصلات النقدية التى توضح قيمة المبيعات أو التوريدات والضريبة المستحقة عليها .$m249$,'b456ef4565d88a950c60a0c4432f60a0'),
(54,0,$m249$المادة 54$m249$,$m249$لا يعتد بأية معاملة يكون الغرض الرئيسى من إقامتها أو أحد أغراضها الرئيسية تجنب الالتزام بالضريبة وضريبة الجدول أو تأجيله أو تخفيض عبء الضريبة ، ويعتبر فى تطبيق هذه المادة تجنبا للضريبة :
1 - التصرفات التى تتم بين الأشخاص المرتبطين فى بيع السلع والخدمات الخاضعة للضريبة وضريبة الجدول ويكون الهدف منها عدم بلوغ أحدهم أو جميعهم حد التسجيل المقرر قانونا .
2 - إنشاء شركات أو تقسيمها أو تجزئة المعاملات لأغراض ضريبية .
ويترتب على اعتبار المعاملة تجنبا للضريبة أحقية المصلحة فى إلزام المكلف بالتسجيل أو أداء الضريبة على أساس القيمة الحقيقية وفقا لظروف السوق وقوى التعامل .
وذلك كله دون الإخلال بحق المكلف فى إثبات أن المعاملة تمت لغير أغراض التجنب الضريبى .
وتشكل لجنة أو أكثر برئاسة رئيس المصلحة أو من يفوضه وعضوية اثنين من العاملين بها بوظيفة مدير عام على الأقل وتختص بنظر حالات التجنب ويكون قرارها ملزما للمأمورية المختصة .$m249$,'ea85e7a2dd81473e46edcb0c1626f595'),
(55,0,$m249$المادة 55$m249$,$m249$يكون للإخطار المرسل بكتاب موصى عليه مصحوبا بعلم الوصول، أو بأية وسيلة إلكترونية لها الحجية فى الإثبات وفقا لقانون التوقيع الإلكترونى الصادر بالقانون رقم 15 لسنة 2004 يصدر بتحديدها قرار من الوزير ، ذات الأثر المترتب على الإعلان الذى يتم بالطرق القانونية ، بما فى ذلك إعلان المحجوز عليه بصورة من محضر الحجز.
ويكون الإخطار صحيحا قانونا سواء تسلمه المسجل من المأمورية المختصة أو من لجنة الطعن المختصة أو تسلمه بمحل المنشأة أو بمحل إقامته المختار .
وفى حالة غلق المنشأة أو غياب المسجل وتعذر إخطاره بإحدى الطرق المشار إليها وكذلك فى حالة رفض المسجل تسلم الإخطار يثبت ذلك بموجب محضر يحرره أحد موظفى المصلحة ممن لهم صفة الضبطية القضائية وينشر ذلك فى لوحة المأمورية أو لجنة الطعن المختصة ، بحسب الأحوال ، مع لصق صورة منه على مقر المنشأة .
وإذا ارتد الإخطار مؤشرا عليه بما يفيد عدم وجود المنشأة أو عدم التعرف على عنوان المسجل يتم إعلانه فى مواجهة النيابة العامة بعد إجراء التحريات اللازمة .
ويعتبر النشر على الوجه السابق والإعلان فى مواجهة النيابة العامة إجراء قاطعا للتقادم .
ويكون للمسجل فى الحالات المنصوص عليها فى الفقرتين الثالثة والرابعة من هذه المادة أن يطعن فى قرار المصلحة بربط الضريبة أو فى قرار لجنة الطعن بحسب الأحوال وذلك خلال ستين يوما من تاريخ توقيع الحجز عليه وإلا أصبح قرار المصلحة بربط الضريبة أو قرار اللجنة نهائيا .$m249$,'7ffe4504171a84c112cc5bd4397b829f'),
(56,0,$m249$المادة 56$m249$,$m249$فى الحالات التى يتم فيها تعديل أو تقدير الضريبة من المصلحة يتم إخطار المسجل بذلك بخطاب موصى عليه مصحوبا بعلم الوصول أو بأية وسيلة إلكترونية لها حجية فى الإثبات وفقا لقانون التوقيع الإلكترونى أو بأية وسيلة كتابية يتحقق بها العلم اليقينى بذلك التعديل أو التقدير .
ويكون للمسجل الطعن على ذلك التعديل أو التقدير خلال ثلاثين يوما من تاريخ علمه بهذا التعديل أو التقدير .
ويكون الطعن المقدم من المسجل على تعديل أو تقدير الضريبة بصحيفة من ثلاث صور يودعها المأمورية المختصة وتسلم إحداها للمسجل مؤشرا عليها من المأمورية بتاريخ إيداعها وتثبت المأمورية فى دفتر خاص بيانات الطعن وملخصا بأوجه الخلاف التى تتضمنها .
وتقوم المصلحة بالبت فى ذلك الطعن بواسطة لجان داخلية يصدر بتشكيلها وتحديد مقارها ونطاق اختصاصها قرار من رئيس المصلحة، وذلك خلال ستين يوما من تاريخ تقديم الطعن .
فإذا تم التوصل إلى تسوية أوجه الخلاف تصبح الضريبة نهائية .
وإذا لم يتم التوصل إلى تسوية أوجه الخلاف تقوم المأمورية بإخطار المسجل بذلك ، وعليها إحالة أوجه الخلاف إلى لجنة الطعن المختصة خلال ثلاثين يوما من تاريخ البت فى هذه الأوجه على أن تقوم بإخطار المسجل بالإحالة بكتاب موصى عليه مصحوبا بعلم الوصول ، فإذا انقضت مدة الثلاثين يوما دون قيام المأمورية بإحالة الخلاف إلى لجنة الطعن المختصة كان للمسجل أن يعرض الأمر كتابة على رئيس هذه اللجنة مباشرة أو بكتاب موصى عليه مصحوبا بعلم الوصول خلال خمسة عشر يوما من تاريخ انتهاء المدة المحددة سالفا ، وعلى رئيس اللجنة خلال خمسة عشر يوما من تاريخ عرض الأمر عليه أو وصول كتاب المسجل إليه أن يحدد جلسة لنظر النزاع ويأمر بضم ملف المسجل .
ويجوز اتخاذ أى من الإجراءات المنصوص عليها فى هذه المادة بأية وسيلة إلكترونية يحددها الوزير .
ويعتبر تعديل أو تقدير الضريبة من قبل المصلحة نهائيا إذا لم يقدم الطعن خلال المواعيد المشار إليها .
وتنظم اللائحة التنفيذية قواعد تشكيل اللجان الداخلية وإجراءات العمل فيها وإثبات الاتفاقات التى تتم أمامها .$m249$,'62a30c0f12ebc3842e7a236f4a53696e'),
(57,0,$m249$المادة 57$m249$,$m249$تشكل لجان الطعن بقرار من الوزير أو من يفوضه من رئيس من غير العاملين بالمصلحة ، وعضوية اثنين من موظفى المصلحة يختارهما الوزير أو من يفوضه ، واثنين من ذوى الخبرة ممن ترشحهم نقابة التجاريين من بين المحاسبين المقيدين فى جدول المحاسبين والمراجعين لشركات الأموال بالسجل العام لمزاولى المهنة الحرة للمحاسبة والمراجعة .
وللوزير أو من يفوضه تعيين أعضاء احتياطيين لموظفى المصلحة باللجان فى المدن التى بها لجنة واحدة ، ويعتبر الأعضاء الأصليون أعضاء احتياطيين بالنسبة إلى اللجان الأخرى فى المدن التى بها أكثر من لجنة ، ويكون ندبهم بدلا من الأعضاء الأصليين الذين يتخلفون عن الحضور من اختصاص رئيس اللجنة الأصلية أو أقدم أعضائها عند غيابه .
ولا يكون انعقاد اللجنة صحيحا إلا إذا حضرها رئيسها وثلاثة من أعضائها على الأقل ، ويتولى أمانة سر اللجنة موظف تندبه المصلحة .
وتكون لجان الطعن دائمة وتابعة مباشرة للوزير ، ويصدر قرار منه أو من يفوضه بتحديدها ، وبيان مقارها ، واختصاصها المكانى ، ومكافآت أعضائها .$m249$,'199a9a7532d627c3a5cb45339a9a8e38'),
(58,0,$m249$المادة 58$m249$,$m249$تختص لجان الطعن بالفصل فى جميع أوجه الخلاف بين المسجلين والمصلحة فى المنازعات المتعلقة بالضرائب المنصوص عليها فى هذا القانون .
وتخطر اللجنة كلا من المسجل والمصلحة بميعاد جلسة نظر الطعن قبل انعقادها بعشرة أيام على الأقل وذلك بكتاب موصى عليه مصحوبا بعلم الوصول ، ولها أن تطلب من كل من المصلحة والمسجل تقديم ما تراه ضروريا من البيانات والأوراق ، وعلى المسجل الحضور أمام اللجنة بنفسه أو بوكيل عنه ، وإلا فصلت اللجنة فى الطعن فى ضوء المستندات المقدمة .
وتصدر اللجنة قرارها فى حدود تقدير المصلحة وطلبات المسجل ، ويعدل ربط الضريبة وفقا لقرار اللجنة ، فإذا لم تكن الضريبة قد حصلت فيكون تحصيلها بمقتضى هذا القرار .$m249$,'c43d4bfb41df8d373958475a5573baac'),
(59,0,$m249$المادة 59$m249$,$m249$تكون جلسات لجان الطعن سرية ، وتصدر قراراتها مسببة بأغلبية أصوات الحاضرين وفى حالة تساوى الأصوات يرجح الجانب الذى منه الرئيس ، ويوقع القرارات كل من الرئيس وأمين السر خلال خمسة عشر يوما على الأكثر من تاريخ صدورها .
وتلتزم اللجنة بمراعاة الأصول والمبادئ العامة لإجراءات التقاضى ، ويعلن كل من المسجل والمصلحة بالقرار الذى تصدره اللجنة بكتاب موصى عليه مصحوبا بعلم الوصول ، وتكون الضريبة واجبة الأداء من واقع قرار لجنة الطعن ، ولا يمنع الطعن فى قرار اللجنة أمام المحكمة المختصة من تحصيل الضريبة .$m249$,'5c9939891879d60089bb83f641b70c7f'),
(60,0,$m249$المادة 60$m249$,$m249$لكل من المصلحة والمسجل الطعن فى قرار اللجنة أمام المحكمة المختصة خلال ستين يوما من تاريخ الإعلان بالقرار .$m249$,'2a78572d9198fc78a0c6a22ba6162f74'),
(61,0,$m249$المادة 61$m249$,$m249$يجوز للمحكمة أن تنظر الدعاوى التى ترفع من المسجل أو عليه فى جلسة سرية ، ويكون الحكم فيها على وجه السرعة .$m249$,'22e42b217d7a9d6cf6b6b570d5a155b8'),
(62,0,$m249$المادة 62$m249$,$m249$تطبق أحكام وإجراءات التحكيم المنصوص عليها فى قانون الجمارك بالنسبة للسلع والخدمات المستوردة التى تخضع لرقابة مصلحة الجمارك .$m249$,'05f744b89c4c2d8fcb51a98ca22ee82b'),
(63,0,$m249$المادة 63$m249$,$m249$لموظفى المصلحة الذين يصدر بتحديد وظائفهم قرار من وزير العدل بالاتفاق مع الوزير صفة مأمورى الضبط القضائى فيما يتعلق بتطبيق أحكام هذا القانون والقرارات المنفذة له .
ولهم فى سبيل ذلك بإذن كتابى من رئيس المصلحة أو من ينيبه ، معاينة المعامل والمصانع والمخازن والمحال والمنشآت وغيرها مما تباشر نشاطا فى سلع أو خدمات خاضعة للضريبة ، ويجوز فى حالات الضبط الاستعانة برجال السلطات الأخرى إذا تطلب الأمر ذلك .$m249$,'1d0f8ed1ca79db55947d0e396c314ab6'),
(64,0,$m249$المادة 64$m249$,$m249$لموظفى المصلحة ممن لهم صفة الضبطية القضائية ، الحق فى الاطلاع على الأوراق والمستندات والدفاتر والسجلات والفواتير والوثائق أيا كان نوعها المتعلقة بتطبيق أحكام هذا القانون وضبطها عند توافر دلائل على وجود مخالفة لأحكامه .
ولهم بإذن كتابى من رئيس المصلحة أو من ينيبه أخذ عينات محددة من السلع للتحليل أو الفحص .
ويلتزم كل شخص يكون له بحكم وظيفته أو اختصاصه أو عمله شأن فى تقدير أو ربط أو تحصيل الضرائب المنصوص عليها فى هذا القانون أو فى الفصل فيما يتعلق بها من منازعات بمراعاة سرية المهنة .
ولا يجوز لأى من العاملين بالمصلحة ممن لا يتصل عملهم بتقدير أو ربط أو تحصيل الضريبة إعطاء أى بيانات أو اطلاع الغير على أية ورقة أو بيان أو ملف أو غيره إلا فى الأحوال المصرح بها قانونا .
ولا يجوز إعطاء بيانات من الملفات الضريبية إلا بناء على طلب كتابى من المسجل أو بناء على نص فى أى قانون آخر .
ولا يعتبر إفشاء للسرية إعطاء بيانات للخلف المشار إليه فى المادة (8) من هذا القانون ، أو تبادل المعلومات والبيانات بين المصالح الإيرادية التابعة لوزارة المالية وفقا للتنظيم الذى يصدر به قرار من الوزير .$m249$,'0cfab0a9f42cbe7acb9680cdd2e170d2'),
(65,0,$m249$المادة 65$m249$,$m249$فى غير حالات التلبس بالجريمة ، لا يجوز اتخاذ أى إجراء من إجراءات التحقيق فى الجرائم التى تقع من موظفى المصلحة ممن لهم صفة الضبطية القضائية أثناء تأدية عملهم أو بسببه إلا بناء على طلب كتابى من الوزير أو من يفوضه .
وفى جميع الأحوال لا يجوز رفع الدعوى الجنائية عليهم إلا بعد الحصول على هذا الطلب .$m249$,'d096bedfe0e3eded41212f39d5dc4735'),
(66,0,$m249$المادة 66$m249$,$m249$يعاقب بغرامة لا تقل عن خمسمائة جنيه ولا تجاوز خمسة آلاف جنيه فضلا عن الضريبة وضريبة الجدول والضريبة الإضافية المستحقة كل من خالف الأحكام والإجراءات أو النظم المنصوص عليها فى هذا القانون ولائحته التنفيذية دون أن يكون عملا من أعمال التهرب المنصوص عليها فيه .
وتعد مخالفة لأحكام هذا القانون الحالات الآتية :
1 - التأخر فى تقديم الإقرار وأداء الضريبة وضريبة الجدول عن المدة المحددة فى المادة (15) من القانون بما لا يجاوز ستين يوما .
2 - تقديم بيانات خاطئة عن المبيعات من السلع أو الخدمات الخاضعة للضريبة إذا ظهرت فيها زيادة عما ورد بالإقرار .
3 - ظهور عجز أو زيادة فى السلع المودعة فى المناطق والأسواق الحرة بالمخالفة لأحكام قانون الجمارك .
4 - عدم إخطار المصلحة بالتغييرات التى حدثت على البيانات الواردة بطلب التسجيل خلال الموعد المحدد .
5 - عدم تمكين موظفى المصلحة من القيام بواجباتهم أو ممارسة اختصاصاتهم فى الرقابة والتفتيش والمعاينة والمراجعة وطلب المستندات أو الاطلاع عليها .
وتضاعف العقوبة فى حالة ارتكاب أى من الأفعال المشار إليها خلال ثلاث سنوات .$m249$,'9b2497ce38bb1a864d7db272546523c5'),
(67,0,$m249$المادة 67$m249$,$m249$مع عدم الإخلال بأية عقوبة أشد منصوص عليها فى أى قانون آخر ، يعاقب على التهرب من الضريبة وضريبة الجدول بالسجن مدة لا تقل عن ثلاث سنوات ولا تجاوز خمس سنوات وبغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز خمسين ألف جنيه أو بإحدى هاتين العقوبتين .
ويجوز الحكم بمصادرة وسائل النقل والأدوات والمواد التى استعملت فى التهريب ، وذلك فيما عدا السفن والطائرات ، ما لم تكن أعدت أو أجرت فعلا بمعرفة مالكيها لهذا الغرض .
ويحكم على الفاعلين متضامنين بالضريبة أو ضريبة الجدول أو كليهما ، بحسب الأحوال ، والضريبة الإضافية .
وتضاعف العقوبة المنصوص عليها بالفقرة الأولى من هذه المادة فى حالة تكرار الجريمة خلال ثلاث سنوات .
وتنظر قضايا التهرب عند إحالتها إلى المحاكم على وجه الاستعجال .
وفى جميع الأحوال تعد جريمة التهرب من الضريبة وضريبة الجدول من الجرائم المخلة بالشرف والأمانة .$m249$,'c72f4e207cb8d3f00bc4c1c73b73f071'),
(68,0,$m249$المادة 68$m249$,$m249$يعد تهربا من الضريبة وضريبة الجدول يعاقب عليه بالعقوبات المنصوص عليها فى المادة (67) من هذا القانون ، ما يأتى :
1 - عدم التقدم للمصلحة للتسجيل فى المواعيد المحددة .
2 - بيع السلعة أو أداء الخدمة أو استيراد أى منهما دون الإقرار عنها ، وسداد الضريبة وضريبة الجدول المستحقة .
3 - خصم الضريبة أو ضريبة الجدول كليا أو جزئيا دون وجه حق بالمخالفة لأحكام وحدود الخصم .
4 - استرداد الضريبة أو ضريبة الجدول كلها أو بعضها دون وجه حق مع العلم بذلك .
5 - تقديم مستندات أو سجلات مزورة أو مصطنعة للتخلص من سداد الضريبة وضريبة الجدول كلها أو بعضها .
6 - عدم إصدار المسجل فواتير عن مبيعاته من السلع أو الخدمات الخاضعة للضريبة وضريبة الجدول .
7 - انقضاء ستين يوما على انتهاء المواعيد المحددة لسداد الضريبة وضريبة الجدول دون الإقرار عنها وسدادها .
8 - إصدار غير المسجل لفواتير محملة بالضريبة وضريبة الجدول .
9 - عدم الالتزام بالقواعد والإجراءات والضوابط التى تكفل انتظام إصدار الفواتير وفقا لأحكام المادة (12) من هذا القانون .
10 - اصطناع فواتير للغير دون أن تكون صادرة عن عمليات بيع حقيقية ، وتقع المسئولية بالتضامن بين مصدر الفاتورة المصطنعة والمستفيد منها .
11 - عدم إمساك المسجل سجلات أو دفاتر محاسبية منتظمة وفقا لأحكام المادة (13) من هذا القانون .
12 - حيازة السلع الخاضعة للضريبة بقصد الاتجار مع العلم بأنها مهربة .
13 - عدم تقديم إقرار ضريبى نهائى ، وتسديد كامل الضريبة المستحقة بموجب هذا القانون خلال ستة أشهر من تاريخ إلغاء التسجيل .
14 - عدم الالتزام بأحكام المادة (40) أو المادة (42) من هذا القانون .
15 - وضع علامات أو أختام مصطنعة للتخلص من سداد ضريبة الجدول كلها أو بعضها .
16 - قيام المنتج أو الموزع أو التاجر ببيع سلع الجدول التى يكون وعاء الضريبة وضريبة الجدول عليها هو سعر بيع المستهلك بسعر أعلى من السعر الذى تم احتساب الضريبة عليه، سواء السعر المعلن من المنتجين أو المستوردين لتلك السلع أو الوارد بالقوائم السعرية المحددة بمعرفة الوزير ، وذلك كله دون سداد الضريبة المستحقة على الزيادة فى السعر .
17 - حيازة سلع الجدول بقصد الاتجار دون أن يكون ملصقا عليها العلامة المميزة (البندرول) والتى يصدر قرار من الوزير بوضع هذه العلامة عليها .
18 - التصرف فى السلع المعفاة من الضريبة وضريبة الجدول أو استعمالها فى غير الغرض الذى أعفيت من أجله خلال فترة الحظر دون إخطار المصلحة وسداد الضريبة المستحقة .
19 - عدم الالتزام بأحكام المادة الرابعة أو المادة الخامسة من مواد الإصدار .$m249$,'db633aa74e58a6f069ef4703c07e581f'),
(69,0,$m249$المادة 69$m249$,$m249$مع عدم الإخلال بالأحكام المنصوص عليها بالمادة (67) من هذا القانون ، يحكم بمصادرة السلع الواردة بالجدول المرافق لهذا القانون موضوع التهرب ، فإذا لم تضبط حكم بما يعادل قيمتها ، ويجوز الحكم بمصادرة وسائل النقل والأدوات والمواد التى استعملت فى التهرب وذلك عدا السفن والطائرات ما لم تكن أعدت خصيصا أو أجرت فعلا لهذا الغرض .$m249$,'bc86318886574d4e15e1e11544eabc65'),
(70,0,$m249$المادة 70$m249$,$m249$فى حالة وقوع أى فعل من أفعال التهرب من الضريبة من أحد الأشخاص الاعتبارية يكون المسئول عنه الشريك المسئول أو المدير أو عضو مجلس الإدارة المنتدب أو رئيس مجلس الإدارة ممن يتولون الإدارة الفعلية على حسب الأحوال .$m249$,'7d8569d78c59b5e2552faf5222ca6756'),
(71,0,$m249$المادة 71$m249$,$m249$يعاقب بالوقف عن ممارسة المهنة لمدة عام وبغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه كل محاسب مقيد بجدول المحاسبين والمراجعين خالف الالتزام المنصوص عليه فى الفقرة الأخيرة من المادة (30) من هذا القانون وفى حالة العود تضاعف العقوبة الأصلية .$m249$,'2ac676e2e6b5efa94de1ee53b922cb37'),
(72,0,$m249$المادة 72$m249$,$m249$لا يجوز رفع الدعوى الجنائية أو اتخاذ أية إجراءات فى جرائم التهرب وغيرها من الجرائم المنصوص عليها فى هذا القانون إلا بناء على طلب من الوزير أو من يفوضه .
ويجوز للوزير أو من يفوضه التصالح فى الجرائم المشار إليها ، وذلك قبل صدور حكم بات فى الدعوى مقابل سداد الضريبة أو ضريبة الجدول المستحقة أو كليهما ، حسب الأحوال ، والضريبة الإضافية ، وذلك بالإضافة إلى تعويض لا يجاوز نصف الحد الأقصى للغرامة المنصوص عليه فى المادة (66) إذا كان التصالح فى جريمة من الجرائم المنصوص عليها بها ، وتعويض يعادل نصف الضريبة أو ضريبة الجدول أو كليهما ، بحسب الأحوال ، إذا كان التصالح فى جريمة من جرائم التهرب ، أما إذا كان التصالح فى الجريمة المنصوص عليها فى المادة (71) من هذا القانون فيتحدد التعويض بما لا يجاوز نصف الحد الأقصى للغرامة المنصوص عليها بها .
ويترتب مباشرة على التصالح انقضاء الدعوى الجنائية وإلغاء ما ترتب على قيامها من آثار بما فى ذلك العقوبة المقضى بها .$m249$,'63901c37dc1d149a8f4b44953bf0b8e8'),
(73,0,$m249$المادة 73$m249$,$m249$للوزير بعد العرض على رئيس مجلس الوزراء وضع نظام أو أكثر لإثابة العاملين بالمصلحة فى ضوء معدلات أدائهم وحجم ومستوى إنجازهم فى العمل .$m249$,'e602c50b8d7f8d6594f2287cfc3e0d05'),
(74,0,$m249$المادة 74$m249$,$m249$يجوز للوزير بعد موافقة مجلس الوزراء تقرير نظام حوافز لتشجيع التعامل بالفواتير الضريبية على أن يتضمن هذا النظام المجالات والشروط والقواعد اللازمة لتنفيذه وذلك بما لا يجاوز (1%) من الضريبة المحصلة سنويا وتحدد اللائحة التنفيذية القواعد المنظمة لذلك .$m249$,'b1accbfb51a4d7c0ac33b46a8c67dc11'),
(1,-2,$m249$الجدول المرافق (سلع وخدمات الجدول)$m249$,$m249$سلع وخدمات الجدول المرافق لمشروع قانون بإصدار قانون الضريبة على القيمة المضافة
م | الصنف | وحدة التحصيل | فئة الضريبة
