31 - الطائرات المدنية، ومحركاتها ، وأجزاؤها ، ومكوناتها ، وقطع غيارها ، والمعدات اللازمة لاستخدامها ، وكذلك الخدمات التى تقدم لهذه الطائرات داخل الدائرة الجمركية، سواء كانت هى أو محركاتها أو أجزاؤها ، ومكوناتها ، وقطع غيارها ، ومعداتها والخدمات التى تقدم لها ، مستوردة أو محلية ، وذلك طبقا للأحكام والقواعد الواردة باتفاق التجارة فى الطائرات المدنية الصادر بشأنها قرار رئيس الجمهورية رقم 414 لسنة 1983
32 - مقاعد ذات عجل وأجزاؤها وقطعها المنفصلة، وأعضاء الجسم الصناعية وأجزاؤها ، وأجهزة تسجيل السمع للصم وأجزاؤها ، وغيرها من الأجهزة التى تلبس أو تحمل أو تزرع فى الجسم لتعويض نقص أو عجز أو عاهة وأجزاؤها ولوازمها ، وأجهزة الغسيل الكلوى وأجزاؤها ولوازمها بما فيها مرشحات الكلى الصناعية، وحضانات الأطفال .
33 - العمليات المصرفية التى يقتصر مباشرتها قانونا على البنوك دون غيرها .
34 - بيع وشراء العملة بشركات الصرافة والبنوك .
35 - خدمات صندوق توفير البريد المصرفية .
36 - الخدمات المالية غير المصرفية الخاضعة لإشراف ورقابة الهيئة العامة للرقابة المالية .
37 - خدمات التأمين وإعادة التأمين .
38 - خدمات التعليم والتدريب والبحث العلمى .
39 - الخدمات الصحية فيما عدا عمليات التجميل والتخسيس لغير الأغراض الطبية .
40 - خدمات النقل البرى للأشخاص بما فى ذلك النقل الذى يتم بواسطة سيارات الأجرة عدا خدمات النقل السياحى والنقل المكيف بين المحافظات وتأجير السيارات الملاكى .
41 - النقل المائى الداخلى غير السياحى للأشخاص، والنقل الجوى للأشخاص .
42 - الخدمات التى تؤدى لإنشاء وصيانة دور العبادة، والخدمات المجانية التى تؤديها دور العبادة .
43 - الخدمات المجانية التى يتم بثها من خلال الإذاعة والتليفزيون أو أى وسيلة أخرى .
44 - خدمات الإنترنت الأرضى (تعفى لمدة عام من تاريخ العمل بقانون الضريبة على القيمة المضافة) .
45 - الخدمات المكتبية التى تقدمها المكتبات العامة أو التابعة للمنشآت التعليمية أو المراكز البحثية أو الثقافية بكافة أنواعها .
46 - خدمات المتاحف التى يصدر بها قرار من الوزير بناء على توصية من الوزير المختص .
47 - الفنون التشكيلية، وأعمال التأليف والنشر الأدبى والفنى بأنواعه .
48 - خدمات وكالات الأنباء .
49 - خدمات استزراع واستنبات ورعاية الأرض والمحاصيل، وعمليات الحصاد وتوريد العمالة الزراعية .
50 - اشتراكات النقابات والهيئات الخاضعة لقانون الهيئات الرياضية بما فيها النوادى الرياضية ومراكز الشباب التى تشرف عليها وزارة الشباب والرياضة، وكذا اشتراكات الجمعيات الأهلية والاجتماعية التى تشرف عليها وزارة التضامن الاجتماعى .
51 - خدمات تجهيز ونقل ودفن الموتى .
52 - السيارات المجهزة طبيا للمعاقين .
53 - النفايات المتحصل عليها من تدوير القمامة .
54 - الأجهزة الناطقة للمكفوفين والأجهزة التى تعمل بطريقة برايل للمكفوفين والبرمجيات والوسائل التعليمية الخاصة بالمكفوفين .
55 - ( أ ) الأدوية والمواد الفعالة الداخلة فى إنتاجها (محلى) .
(ب) الأدوية والمواد الفعالة الداخلة فى إنتاجها (مستورد) .
56 - الخدمات التعليمية التى يقوم بها الأقسام والمدارس والمعاهد والكليات والجامعات التى تقوم بتدريس مناهج ذات طبيعة خاصة (الدولية) .
57 - الخدمات الإعلانية .$m249$,'210d403e75fe46d564584e188f4be1c8',DATE '2016-09-08',NULL,'active',NULL,NULL,$m249$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 35 مكرر (ج) فى 7 سبتمبر 2016 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m249$);

DO $m249$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m249_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m249_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[249] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m249_art) <> 87 OR (SELECT sum(char_length(body)) FROM m249_art) <> 58056 OR (SELECT count(*) FROM m249_ver) <> 87 THEN
    RAISE EXCEPTION '[249] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=67 AND law_year=2016 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%القيمة المضافة%' THEN
    RAISE EXCEPTION '[249] يوجد مستند آخر برقم 67 لسنة 2016 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (67, 2016, $t249$القانون رقم 67 لسنة 2016 بإصدار قانون الضريبة على القيمة المضافة (النص الأصلى كما نشر بالجريدة الرسمية)$t249$, $t249$قانون الضريبة على القيمة المضافة 67/2016$t249$, 'other', 'in_force', NULL, DATE '2016-09-05', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m249_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m249_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m249_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 87 THEN
    RAISE EXCEPTION '[249] عدد صفوف النص % بدل 87', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 87 THEN
    RAISE EXCEPTION '[249] عدد نسخ النص % بدل 87', v_vcnt;
  END IF;
  RAISE NOTICE '[249] قانون 67/2016: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m249$;
